export const COMMUNITY_GLOSSARY_FULL = Object.values(SECTIONS).join("\n\n");

/** 按类别读取术语（类别名见 COMMUNITY_GLOSSARY_CATEGORIES）；未知类别返回 null。 */
export function glossaryByCategory(category: string): string | null {
  return SECTIONS[category] ?? null;
}
